// Raises every CocoaPods target to a minimum iOS deployment target.
//
// Xcode 27 rejects deployment targets below 15.0, but some pods (e.g. the
// resource-bundle targets of react-native-svg and async-storage) still declare
// 12.4/13.4, which fails the build. `ios/` is generated by prebuild, so the fix
// lives here as a Podfile post_install hook rather than a hand edit.

const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');

const MIN_TARGET = '15.1';

module.exports = function withPodDeploymentTarget(config) {
  return withDangerousMod(config, [
    'ios',
    (cfg) => {
      const podfile = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      const contents = fs.readFileSync(podfile, 'utf8');
      const result = mergeContents({
        tag: 'postpilot-pod-deployment-target',
        src: contents,
        newSrc: [
          '    installer.pods_project.targets.each do |target|',
          '      target.build_configurations.each do |bc|',
          `        if bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'].to_f < ${MIN_TARGET}`,
          `          bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN_TARGET}'`,
          '        end',
          '      end',
          '    end',
        ].join('\n'),
        anchor: /post_install do \|installer\|/,
        offset: 1,
        comment: '#',
      });
      fs.writeFileSync(podfile, result.contents);
      return cfg;
    },
  ]);
};
